function aDash(){return `<h1>Users & roles</h1><p class="mu" style="margin:4px 0 16px">Role changes take effect immediately and are enforced on the server.</p><div class="grid g4" style="margin-bottom:18px">${["Administrator","Examiner","Candidate"].map(r=>`<div class="stat"><b>${U.filter(u=>u.role==r).length}</b>${r}s</div>`).join("")}</div><div class="card tw"><table><tr><th>Name</th><th>Email</th><th>Role</th><th></th></tr>${U.map(u=>`<tr><td><b>${u.name}</b></td><td class="mu">${u.email}</td><td><select style="width:150px" onchange="u=U.find(x=>x.id==${u.id});u.role=this.value;toast('Role updated')">${["Administrator","Examiner","Candidate"].map(r=>`<option ${r==u.role?"selected":""}>${r}</option>`).join("")}</select></td><td><span class="pill ok">Active</span></td></tr>`).join("")}</table></div>`}
